-- =====================================================
-- 6. ACCOUNTS
-- Every account's password is SlisDemo2026!. Matched by email: created if
-- absent, name/role/password reset if present. Four teachers have no
-- section, so there is someone to assign.
-- =====================================================

SELECT setval('users_user_id_seq', GREATEST((SELECT MAX(user_id) FROM users), 1));

ON CONFLICT (email) DO UPDATE
  SET name = EXCLUDED.name, role = EXCLUDED.role, password = EXCLUDED.password;

SELECT setval('users_user_id_seq', GREATEST((SELECT MAX(user_id) FROM users), 1));


