-- Holidays, the Christmas break, three quarter breaks (the at-risk model reads
-- quarter windows from them), four grading periods (the admin home reads the
-- current quarter and its due date from them), exams and school events.
-- =====================================================

SELECT '2025-2026', v.title, v.typ, v.s::date, v.e::date, v.descr, v.gp, now(), now()
  FROM (VALUES
    ('Enrollment Period', 'enrollment', '2025-05-05', '2025-05-30', 'Regular enrollment for S.Y. 2025-2026.', NULL),
    ('1st Quarter', 'grading_period', '2025-06-02', '2025-08-22', '1st Quarter grades are due on the last day.', '1st_quarter'),
    ('Opening of Classes', 'event', '2025-06-02', '2025-06-02', NULL, NULL),
    ('Eid''l Adha (Feast of Sacrifice)', 'holiday', '2025-06-06', '2025-06-06', NULL, NULL),
    ('Independence Day', 'holiday', '2025-06-12', '2025-06-12', NULL, NULL),
    ('Nutrition Month Culminating Program', 'event', '2025-07-31', '2025-07-31', NULL, NULL),
    ('Buwan ng Wika Celebration', 'event', '2025-08-15', '2025-08-15', NULL, NULL),
    ('1st Quarter Examinations', 'exam', '2025-08-20', '2025-08-22', NULL, NULL),
    ('Ninoy Aquino Day', 'holiday', '2025-08-21', '2025-08-21', NULL, NULL),
    ('End of 1st Quarter Break', 'quarter_break', '2025-08-25', '2025-08-29', NULL, NULL),
    ('National Heroes Day', 'holiday', '2025-08-25', '2025-08-25', NULL, NULL),
    ('2nd Quarter', 'grading_period', '2025-09-01', '2025-11-21', '2nd Quarter grades are due on the last day.', '2nd_quarter'),
    ('Parent-Teacher Conference (1st Quarter Cards)', 'other', '2025-09-05', '2025-09-05', 'Release of 1st quarter report cards.', NULL),
    ('Teachers'' In-Service Training', 'school_day_off', '2025-10-17', '2025-10-17', 'No classes; faculty in-service training.', NULL),
    ('United Nations Day Celebration', 'event', '2025-10-24', '2025-10-24', NULL, NULL),
    ('All Saints'' Day Eve', 'holiday', '2025-10-31', '2025-10-31', NULL, NULL),
    ('All Saints'' Day', 'holiday', '2025-11-01', '2025-11-01', NULL, NULL),
    ('2nd Quarter Examinations', 'exam', '2025-11-19', '2025-11-21', NULL, NULL),
    ('Semestral Break', 'quarter_break', '2025-11-24', '2025-11-28', NULL, NULL),
    ('Bonifacio Day', 'holiday', '2025-11-30', '2025-11-30', NULL, NULL),
    ('3rd Quarter', 'grading_period', '2025-12-01', '2026-01-23', '3rd Quarter grades are due on the last day.', '3rd_quarter'),
    ('Feast of the Immaculate Conception', 'holiday', '2025-12-08', '2025-12-08', NULL, NULL),
    ('Christmas Program', 'event', '2025-12-19', '2025-12-19', NULL, NULL),
    ('Christmas Break', 'school_day_off', '2025-12-20', '2026-01-04', 'Classes resume on January 5, 2026.', NULL),
    ('Christmas Eve', 'holiday', '2025-12-24', '2025-12-24', NULL, NULL),
    ('Christmas Day', 'holiday', '2025-12-25', '2025-12-25', NULL, NULL),
    ('Rizal Day', 'holiday', '2025-12-30', '2025-12-30', NULL, NULL),
    ('Last Day of the Year', 'holiday', '2025-12-31', '2025-12-31', NULL, NULL),
    ('New Year''s Day', 'holiday', '2026-01-01', '2026-01-01', NULL, NULL),
    ('3rd Quarter Examinations', 'exam', '2026-01-21', '2026-01-23', NULL, NULL),
    ('End of 3rd Quarter Break', 'quarter_break', '2026-01-26', '2026-01-30', NULL, NULL),
    ('4th Quarter', 'grading_period', '2026-02-02', '2026-03-31', '4th Quarter grades are due on the last day.', '4th_quarter'),
    ('School Foundation Day', 'event', '2026-02-13', '2026-02-13', NULL, NULL),
    ('Chinese New Year', 'holiday', '2026-02-17', '2026-02-17', NULL, NULL),
    ('EDSA People Power Revolution Anniversary', 'holiday', '2026-02-25', '2026-02-25', NULL, NULL),
    ('Eid''l Fitr (Feast of Ramadan)', 'holiday', '2026-03-20', '2026-03-20', NULL, NULL),
    ('4th Quarter Examinations', 'exam', '2026-03-25', '2026-03-27', NULL, NULL),
    ('Graduation Rites (Grade 12)', 'event', '2026-03-28', '2026-03-28', NULL, NULL),
    ('Moving-Up and Recognition Ceremony', 'event', '2026-03-30', '2026-03-30', NULL, NULL)
  ) AS v(title, typ, s, e, descr, gp)
 WHERE NOT EXISTS (
         SELECT 1 FROM academic_calendar_events x
          WHERE x.school_year = '2025-2026' AND x.event_type = v.typ AND lower(x.title) = lower(v.title))
   AND (v.gp IS NULL OR NOT EXISTS (
         SELECT 1 FROM academic_calendar_events x
          WHERE x.school_year = '2025-2026' AND x.grading_period = v.gp));


