-- =====================================================
-- 12. SCORE ENTRIES, GRADES AND OBSERVED VALUES
-- Every grade is the DO 8 transmutation of its own score entries, computed the
-- way the grading calculator does, so the two always agree. Components are
-- resolved from each subject's own template.
-- =====================================================

CREATE TEMP TABLE seed_scores (eid bigint, code text, comp text, period text, label text, score numeric, top numeric, rec timestamp) ON COMMIT DROP;





SELECT s.eid, sub.subject_id, gc.grading_component_id, s.period, s.label, s.score, s.top, s.rec
  FROM seed_scores s
  JOIN subjects sub ON sub.subject_code = s.code
  JOIN grading_components gc ON gc.grading_template_id = sub.grading_template_id AND gc.component_name = s.comp;

DO $$
BEGIN
  IF (SELECT count(*) FROM seed_scores) <>
     (SELECT count(*) FROM score_entries WHERE enrollment_id IN (SELECT DISTINCT eid FROM seed_scores)) THEN
    RAISE EXCEPTION 'score entries did not all resolve to a subject and component';
  END IF;
END $$;

