-- =====================================================
-- 13. ATTENDANCE
-- Present on every school day of each enrollment's span -- weekdays, minus the
-- holidays, days off and quarter breaks above -- except the listed absences,
-- excused days and late arrivals. Recorded by the section's adviser.
-- =====================================================

CREATE TEMP TABLE seed_att_ranges (eid bigint, d_from date, d_to date, adviser text) ON COMMIT DROP;

CREATE TEMP TABLE seed_att_exceptions (eid bigint, day date, status text, remarks text) ON COMMIT DROP;

SELECT r.eid, g.day, COALESCE(x.status, 'P'), x.remarks, u.user_id,
       g.day + time '07:40', g.day + time '07:40'
  FROM seed_att_ranges r
  CROSS JOIN LATERAL (SELECT gs::date AS day FROM generate_series(r.d_from, r.d_to, interval '1 day') gs) g
  LEFT JOIN seed_att_exceptions x ON x.eid = r.eid AND x.day = g.day
  LEFT JOIN users u ON u.email = r.adviser
 WHERE extract(isodow FROM g.day) < 6
   AND NOT EXISTS (
         SELECT 1 FROM academic_calendar_events ev
          WHERE ev.school_year = '2025-2026'
            AND ev.event_type IN ('holiday', 'school_day_off', 'quarter_break')
            AND g.day BETWEEN ev.start_date AND ev.end_date);

DO $$
BEGIN
  IF (SELECT count(*) FROM seed_att_exceptions x
       WHERE NOT EXISTS (SELECT 1 FROM attendance_records a
                          WHERE a.enrollment_id = x.eid AND a.date = x.day AND a.status = x.status)) > 0 THEN
    RAISE EXCEPTION 'an absence/late day fell outside the school days';
  END IF;
END $$;


-- =====================================================
-- 14. INVOICES, INSTALLMENTS AND PAYMENTS
-- Computed with billing-service's own rules: the discount waterfall on tuition
-- (voucher, scholarships, payment plan, Early Bird), installments counted from
-- the year's start month and due on the last day of the month, remainder on the
-- last one. Senior High is billed once a year, on the 1st-semester enrollment.
-- Joshua's schedule is prorated from his transfer-in date. Installments still
-- owed past their due date are overdue, as flag_overdue_installments marks them.
-- =====================================================

OVERRIDING SYSTEM VALUE VALUES
  (300, 200, 'INV-2025-000300', '2025-05-20', 'paid', 'monthly', '2025-06-30'),
