SELECT v.inv, dt.discount_type_id, v.descr, v.amount
  FROM (VALUES
    (300, NULL, 'Scholarship discount (1 item)', 850.00),
    (300, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 807.50),
    (301, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 850.00),
    (302, 'SEMI_ANNUAL_PLAN', 'Semi-Annual Payment Plan', 570.00),
    (302, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 921.50),
    (304, NULL, 'Scholarship discount (2 items)', 5700.00),
    (304, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 665.00),
    (305, 'ANNUAL_PLAN', 'Annual Payment Plan', 950.00),
    (305, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 902.50),
    (307, NULL, 'Voucher — Education Service Contracting (ESC)', 14000.00),
    (307, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 450.00),
    (308, 'SEMI_ANNUAL_PLAN', 'Semi-Annual Payment Plan', 810.00),
    (308, 'EARLY_BIRD', 'Early Bird (invoiced on or before 2025-06-07)', 1309.50)
  ) AS v(inv, code, descr, amount)
  LEFT JOIN discount_types dt ON dt.discount_code = v.code;



DO $$
DECLARE bad int;
BEGIN
  SELECT count(*) INTO bad
    FROM student_invoices i
   WHERE i.enrollment_id IN (SELECT e.enrollment_id FROM enrollments e JOIN students s USING (student_id)
                              WHERE s.lrn LIKE '136700000%')
     AND (  (SELECT COALESCE(sum(amount), 0) FROM student_invoice_items x WHERE x.invoice_id = i.invoice_id)
          - (SELECT COALESCE(sum(amount), 0) FROM student_invoice_discounts x WHERE x.invoice_id = i.invoice_id))
         <> (SELECT sum(amount) FROM invoice_installments x WHERE x.invoice_id = i.invoice_id)
      OR (SELECT COALESCE(sum(amount_paid), 0) FROM student_payments x WHERE x.invoice_id = i.invoice_id)
         <> (SELECT sum(amount_paid) FROM invoice_installments x WHERE x.invoice_id = i.invoice_id);
  IF bad > 0 THEN
    RAISE EXCEPTION '% seeded invoice(s) do not reconcile', bad;
  END IF;
END $$;


-- =====================================================
-- 15. SEQUENCES
-- Explicit ids above do not advance their sequences; move them past the rows.
-- =====================================================

SELECT setval(pg_get_serial_sequence('households', 'household_id'), GREATEST((SELECT MAX(household_id) FROM households), 1));
SELECT setval(pg_get_serial_sequence('students', 'student_id'), GREATEST((SELECT MAX(student_id) FROM students), 1));
SELECT setval(pg_get_serial_sequence('enrollments', 'enrollment_id'), GREATEST((SELECT MAX(enrollment_id) FROM enrollments), 1));
SELECT setval(pg_get_serial_sequence('student_invoices', 'invoice_id'), GREATEST((SELECT MAX(invoice_id) FROM student_invoices), 1));

COMMIT;
